// Package info contains variables with useful info about the elk environment
package info

// Contains the version of Elk currently in use
var Version string
var CurrentMode Mode

type Mode uint16

const (
	InterpretMode = iota
	NativeMode
	ReplInterpretMode
	ReplDisassemble
	ReplLex
	ReplTranspile
	ReplNative
	ReplParse
	ReplTypecheck
	ReplExpand
)

func (m Mode) Description() string {
	return ModeDescriptions[m]
}

var ModeDescriptions = []string{
	InterpretMode:     "interpreter",
	NativeMode:        "native",
	ReplInterpretMode: "REPL interpreter",
	ReplDisassemble:   "REPL disassemble bytecode",
	ReplLex:           "REPL tokenizer",
	ReplTranspile:     "REPL transpile to Go source",
	ReplNative:        "REPL compile to binary and execute",
	ReplParse:         "REPL parse to AST",
	ReplTypecheck:     "REPL typecheck",
	ReplExpand:        "REPL expand macros",
}

func init() {
	if Version == "" {
		Version = "dev"
	}
}

